<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $unit = $report['content_unit']; ?>
<dl class="ps-coa-history-metrics">
	<div><dt><?php esc_html_e( 'Purity', 'pepselect-coa-archive' ); ?><?php if ( ! empty( $report['purity_status']['success'] ) ) : ?><span>✓ <?php esc_html_e( 'Pass', 'pepselect-coa-archive' ); ?></span><?php endif; ?></dt><dd><?php echo '' !== $report['purity_percentage_display'] ? esc_html( $report['purity_percentage_display'] . '%' ) : '—'; ?></dd><small><?php echo esc_html( $report['purity_method'] ?: __( 'Laboratory result', 'pepselect-coa-archive' ) ); ?></small></div>
	<div><dt><?php esc_html_e( 'Average Net Content', 'pepselect-coa-archive' ); ?></dt><dd><?php echo '' !== $report['average_net_content_display'] ? esc_html( trim( $report['average_net_content_display'] . ' ' . $unit ) ) : '—'; ?></dd><small><?php if ( $report['minimum_net_content_display'] || $report['maximum_net_content_display'] ) { echo esc_html( sprintf( __( 'Range %1$s–%2$s %3$s', 'pepselect-coa-archive' ), $report['minimum_net_content_display'], $report['maximum_net_content_display'], $unit ) ); } else { esc_html_e( 'Not reported', 'pepselect-coa-archive' ); } ?></small></div>
	<div><dt><?php esc_html_e( 'Labeled Content', 'pepselect-coa-archive' ); ?></dt><dd><?php echo '' !== $report['claimed_content_display'] ? esc_html( trim( $report['claimed_content_display'] . ' ' . $unit ) ) : '—'; ?></dd><small><?php esc_html_e( 'As stated on vial label', 'pepselect-coa-archive' ); ?></small></div>
	<div><dt><?php esc_html_e( 'Vials Tested', 'pepselect-coa-archive' ); ?></dt><dd><?php echo '' !== $report['vials_tested_display'] ? esc_html( $report['vials_tested_display'] ) : '—'; ?></dd><small><?php echo '' !== $report['vials_tested_display'] ? esc_html( sprintf( __( 'n = %s · destructive testing', 'pepselect-coa-archive' ), $report['vials_tested_display'] ) ) : esc_html__( 'Not reported', 'pepselect-coa-archive' ); ?></small></div>
</dl>
